<?php
use NxMultiTool\Registry;
use NxMultiTool\AdminController;
$exportQuery = $_GET; $exportQuery['tool'] = 'access_log'; $exportQuery['_csrf_token'] = \app\Core\Csrf::token();
?>
<section class="nxmt-panel"><form method="get" action="<?= e(Registry::url()) ?>"><input type="hidden" name="tool" value="access_log"><div class="nxmt-fields"><?php foreach (['q' => ['検索（URL・参照元・UA）', 'search'], 'ip' => ['IP', 'text'], 'from' => ['開始日', 'date'], 'to' => ['終了日', 'date']] as $key => $field): ?><label><?= e($field[0]) ?><input name="<?= e($key) ?>" type="<?= e($field[1]) ?>" value="<?= e(is_string($_GET[$key] ?? null) ? $_GET[$key] : '') ?>"></label><?php endforeach; ?></div><button type="submit">絞り込む</button> <a class="button secondary" href="<?= e(Registry::endpoint('export') . '?' . http_build_query($exportQuery)) ?>">CSV出力</a></form><p class="nxmt-muted">日時はCMSのタイムゾーンです。管理画面・ログイン中のアクセス・静的ファイルは記録しません。URLと参照元のクエリ・認証情報は保存しません。キャッシュから直接返されたアクセスは記録されないことがあります。</p></section>
<form id="nxmt-log-bulk" method="post" action="<?= e(Registry::endpoint('action')) ?>" class="nxmt-inline"><?php AdminController::form('access_log', 'delete_selected'); ?><button type="submit" class="secondary" data-confirm="選択したログを削除しますか？">選択ログを削除</button></form>
<div class="nxmt-table-wrap"><table><thead><tr><th>選択</th><th>日時</th><th>HTTP</th><th>IP・拒否状態</th><th>URL</th><th>参照元</th><th>UA</th></tr></thead><tbody><?php foreach ($data['rows'] as $row): ?><tr><td><input form="nxmt-log-bulk" type="checkbox" name="ids[]" value="<?= (int)$row['id'] ?>" aria-label="ログ<?= (int)$row['id'] ?>"></td><td><?= e(date('Y-m-d H:i:s', $row['created_at'])) ?></td><td><?= e($row['method']) ?> <?= (int)$row['status'] ?></td><td><?= e($row['ip']) ?><small><?= isset($data['blocks'][$row['ip']]) ? e('拒否中: ' . date('Y-m-d H:i', $data['blocks'][$row['ip']]['until'])) : '未拒否' ?></small><form method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('access_log', isset($data['blocks'][$row['ip']]) ? 'unblock' : 'block'); ?><input type="hidden" name="ip" value="<?= e($row['ip']) ?>"><button type="submit" class="secondary" data-confirm="このIPの拒否状態を変更しますか？"><?= isset($data['blocks'][$row['ip']]) ? '拒否解除' : '期限付き拒否' ?></button></form><a href="<?= e(Registry::url('comment_manager') . '&q=' . rawurlencode($row['ip'])) ?>">同じIPのコメント</a></td><td><?= e($row['url']) ?></td><td><?= e($row['referrer']) ?></td><td><?= e($row['ua']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php AdminController::pagination('access_log', $page, $data['total']); ?>
<section class="nxmt-panel"><h2>ログの整理</h2><div class="nxmt-fields"><form method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('access_log', 'purge'); ?><label>指定日数より古いログを削除<input type="number" name="days" value="30" min="1" max="365"></label><button class="secondary" data-confirm="古いログを削除しますか？">削除</button></form><form method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('access_log', 'truncate'); ?><label>全ログ削除の確認（DELETEと入力）<input name="confirm" required pattern="DELETE" autocomplete="off"></label><button class="danger" data-confirm="全ログを削除します。取り消せません。">全ログを削除</button></form></div><h3>現在の拒否リスト</h3><?php foreach ($data['blocks'] as $ip => $block): ?><form class="nxmt-inline" method="post" action="<?= e(Registry::endpoint('action')) ?>"><?php AdminController::form('access_log', 'unblock'); ?><input type="hidden" name="ip" value="<?= e($ip) ?>"><span><?= e($ip) ?> · <?= e(date('Y-m-d H:i', $block['until'])) ?>まで</span><button class="secondary">拒否解除</button></form><?php endforeach; ?></section>
